from abc import ABC, abstractmethod
from typing import Protocol

class Notifier(Protocol):
    def send(self, message: str) -> str: ...

class BaseNotifier(ABC):
    @abstractmethod
    def send(self, message: str) -> str:
        raise NotImplementedError

class ConsoleNotifier(BaseNotifier):
    def send(self, message: str) -> str:
        return f'notice: {message}'

class FakeNotifier:
    def send(self, message: str) -> str:
        return f'fake: {message}'

class Reminder:
    def __init__(self, notifier: Notifier):
        self.notifier = notifier

    def send(self, topic: str) -> str:
        return self.notifier.send(f'Review {topic}')

print(Reminder(ConsoleNotifier()).send('Loops'))
print(Reminder(FakeNotifier()).send('Loops'))
try:
    BaseNotifier()
except TypeError:
    print('abstract class blocked')

lab.testCode:
assert Reminder(ConsoleNotifier()).send('Loops')=='notice: Review Loops'
assert Reminder(FakeNotifier()).send('Loops')=='fake: Review Loops'
try: BaseNotifier()
except TypeError: pass
else: raise AssertionError('abstract class instantiated')
print('PASS: notifier contracts')
